import math

def build_agent(sandbox):
    # Sled is a sliding body, no need to create additional bodies
    return None

def agent_action(sandbox, agent_body, step_count):
    pos = sandbox.get_sled_position()
    if pos is None:
        return
    x, y = pos
    vel = sandbox.get_sled_velocity() or (0.0, 0.0)
    vx, vy = vel
    speed = math.hypot(vx, vy)

    # Check if checkpoints are passed
    past_a = sandbox.get_checkpoint_a_reached()
    past_b = sandbox.get_checkpoint_b_reached()

    # Determine target based on current state
    if not past_a:
        target_x, target_y = 17.5 + (19.0 - 17.5)/2, 3.8 + (4.5 - 3.8)/2  # Alpha center
    elif not past_b:
        target_x, target_y = 23.0 + (24.5 - 23.0)/2, 2.5 + (3.2 - 2.5)/2  # Beta center
    else:
        target_x, target_y = 28.0 + (32.0 - 28.0)/2, 2.2 + (2.8 - 2.2)/2  # Target center

    # Calculate direction to target
    dx = target_x - x
    dy = target_y - y
    distance = math.hypot(dx, dy)
    if distance < 0.001:
        distance = 0.001
    dir_x = dx / distance
    dir_y = dy / distance

    # Adjust speed based on proximity to checkpoints
    if not past_a:
        desired_speed = 3.5  # Higher speed for initial phase
    elif not past_b:
        desired_speed = 2.5  # Slightly slower for Beta
    else:
        desired_speed = 1.5  # Slower for target

    # Adjust thrust based on current speed and environment feedback
    if speed < desired_speed * 0.5:
        # Need to speed up
        thrust_mag = 500.0
    elif speed > desired_speed * 1.5:
        # Need to slow down
        thrust_mag = 200.0
    else:
        thrust_mag = 400.0

    # Add altitude adjustment for checkpoints
    if not past_a:
        # Maintain higher altitude for Alpha
        if y < 3.8:
            thrust_mag *= 1.2
    elif not past_b:
        # Maintain moderate altitude for Beta
        if y < 2.5:
            # Apply vertical thrust to maintain altitude
            if vy < 0:
                thrust_mag *= 1.3
                dir_y = 0.0  # Focus on horizontal movement
        else:
            thrust_mag *= 1.1
    else:
        # Adjust for target zone
        if y < 2.2:
            thrust_mag *= 1.2
            dir_y = 0.0  # Focus on horizontal movement

    # Apply thrust
    sandbox.apply_thrust(thrust_mag * dir_x, thrust_mag * dir_y)

