    x, y = pos
    vel = sandbox.get_sled_velocity() or (0.0, 0.0)
    vx, vy = vel
    speed = math.hypot(vx, vy)

    # Check if checkpoints are passed
    past_a = sandbox.get_checkpoint_a_reached()
    past_b = sandbox.get_checkpoint_b_reached()

    # Determine target based on current state
    if not past_a:
        # Check if in Alpha zone to transition to Beta
        if 17.5 <= x <= 19.0 and 3.8 <= y <= 4.5:
            target_x, target_y = 23.0 + (24.5 - 23.0)/2, 2.5 + (3.2 - 2.5)/2  # Beta center
        else:
            target_x, target_y = 17.5 + (19.0 - 17.5)/2, 3.8 + (4.5 - 3.8)/2  # Alpha center
    elif not past_b:
        # Check if in Beta zone to transition to target
        if 23.0 <= x <= 24.5 and 2.5 <= y <= 3.2:
            target_x, target_y = 28.0 + (32.0 - 28.0)/2, 2.2 + (2.8 - 2.2)/2  # Target center
        else:
            target_x, target_y = 23.0 + (24.5 - 23.0)/2, 2.5 + (3.2 - 2.5)/2  # Beta center
    else:
        # Final target
        target_x, target_y = 28.0 + (32.0 - 28.0)/2, 2.2 + (2.8 - 2.2)/2  # Target center

    # Calculate direction to target
    dx = target_x - x
    dy = target_y - y
    distance = math.hypot(dx, dy)
    if distance < 0.001:
        distance = 0.001
    dir_x = dx / distance
    dir_y = dy / distance

    # Adjust direction based on checkpoint zone proximity
    if not past_a:
        # Check if y is below Alpha's lower bound
        if y < 3.8:
            # Increase y-component of direction to enter Alpha zone
            dir_y = 0.8  # Adjusted y-component
        # Check if y is above Alpha's upper bound
        if y > 4.5:
            # Decrease y-component of direction to exit Alpha zone
            dir_y = -0.8  # Adjusted y-component
    elif not past_b:
        # Check if y is below Beta's lower bound
        if y < 2.5:
            # Increase y-component of direction to enter Beta zone
            dir_y = 0.8
        # Check if y is above Beta's upper bound
        if y > 3.2:
            # Decrease y-component of direction to exit Beta zone
            dir_y = -0.8

    # Calculate desired speed based on phase and altitude
    if not past_a:
        desired_speed = 3.5
        if y < 3.8:
            desired_speed *= 1.2  # Increase speed to maintain altitude
    elif not past_b:
        desired_speed = 2.5
        if y < 2.5:
            desired_speed *= 1.3  # Increase speed to maintain altitude
    else:
        desired_speed = 1.8  # Slower speed for final target

    # Adjust thrust based on current speed and desired speed
    if speed < desired_speed * 0.5:
        thrust_mag = 500.0  # Increase thrust to accelerate
    elif speed > desired_speed * 1.5:
        thrust_mag = 200.0  # Decrease thrust to decelerate
    else:
        thrust_mag = 450.0  # Maintain speed

    # Apply thrust with direction and magnitude
    sandbox.apply_thrust(thrust_mag * dir_x, thrust_mag * dir_y)
